callGraph.callee:
bars
            .iter()
            .map(|beats| Bar {
                clef: Clef::Treble8vb,
                voices: vec![Voice {
                    beats: beats.clone(),
                }],
            }).collect

beat
        .notes
        .iter()
        .filter_map(|n| match n.place {
            NotePlace::Fretted { string, fret } if (1..=6).contains(&string) && fret <= FRETS => {
                Some(format!("{string}:{fret}"))
            }
            _ => {
                add_n(
                    losses,
                    "notes off a six-string guitar's 24 frets are left out",
                    place,
                    1,
                );
                None
            }
        }).collect

score
        .tracks
        .iter()
        .map(|track| {
            let strings = track
                .staves
                .iter()
                .map(|s| s.tuning.len())
                .max()
                .unwrap_or(0);
            let mut counts = Counts {
                name: track.name.clone(),
                struck: vec![0; strings],
                tied: vec![0; strings],
            };
            let notes = track
                .staves
                .iter()
                .flat_map(|s| &s.bars)
                .flat_map(|b| &b.voices)
                .flat_map(|v| &v.beats)
                .flat_map(|b| &b.notes);
            for note in notes {
                if let NotePlace::Fretted { string, .. } = note.place
                    && let Some(i) = usize::from(string).checked_sub(1).filter(|&i| i < strings)
                {
                    counts.struck[i] += 1;
                    counts.tied[i] += u32::from(note.tie);
                }
            }
            counts
        }).collect
